contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract with a single play call; amount is provided by the test harness.
    // We check that when a play does NOT immediately pay out (i.e., random != 0 branch),
    // the contract's pot equals the previous pot plus exactly the ticket price (not more),
    // which holds for the original contract P (require ==) but is violated by M (require >=).
    function run(uint amount) public {
        // must have enough balance to send
        require(address(this).balance >= amount);

        // record pot before
        uint before = c.pot();

        // make the play call with provided amount
        c.play{value: amount}();

        // record pot after
        uint after = c.pot();

        // The general rule (holds on P): if no payout occurred then after == before + c.TICKET_AMOUNT()
        // We cannot observe whether payout occurred directly, but we can detect payout by checking
        // that address(c).balance decreased (payout to player or bank). If balance did not decrease,
        // then no payout happened and pot must have increased by exactly TICKET_AMOUNT.
        uint balBefore = address(c).balance + 0; // read current balance (after call)

        // Because we only have balances after the call, infer payout absence by comparing
        // after pot to before: in P, if no payout happened pot increases by exactly TICKET_AMOUNT.
        // So assert that if after > before then after == before + c.TICKET_AMOUNT().
        // This distinguishes M: with amount > TICKET_AMOUNT pot becomes before + amount, breaking the rule.
        assert(!(after > before) || after == before + c.TICKET_AMOUNT());
    }

    // Allow contract to receive Ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint paidHigh, uint paidLow) public payable {
        require(paidLow <= paidHigh);
        require(address(this).balance >= paidHigh);
        bool revertedHigh;
        try c.play{value: paidHigh}() { revertedHigh = false; } catch { revertedHigh = true; }
        bool revertedLow;
        try c.play{value: paidLow}() { revertedLow = false; } catch { revertedLow = true; }
        // If the call with higher payment reverted then a call with any lower-or-equal payment must also revert
        assert(!revertedHigh || revertedLow);
    }
    receive() external payable {}
}

