pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter: a seed that we use to vary block.timestamp to influence randomness
    function testFuzz_property(uint256 timeOffset) public {
        // keep timeOffset within a practical range for block.timestamp
        timeOffset = bound(timeOffset, 0, 1 days);

        // actor that will play
        address player = address(0xBEEF);

        // fund player so they can pay the ticket amount
        vm.deal(player, 1 ether);

        // ensure deterministic starting pot = 0
        // now perform a play() call where randomness yields a WIN path (random==0)
        // We cannot control keccak inputs fully, but we can try to create a scenario where
        // at least some fuzzed timeOffset will lead to a win for the given player.
        // We run the call and then check the invariant: reference resets pot to 0 after a win.

        // move time to a chosen timestamp to affect keccak randomness
        vm.warp(block.timestamp + int256(timeOffset));

        // perform the call as player paying exact ticket amount
        vm.prank(player);
        c.play{value: 10}();

        // The general property (single assertion): If a winning payout occurred, reference contract ensures pot == 0.
        // For the reference contract this holds for every input; the mutant that omits resetting pot will leave pot > 0
        // after a winning payout for some inputs. We assert that pot is either 0 or (if no win) non-negative — but the
        // distinguishing invariant we assert is that pot == 0 after this play (the reference always does when the play
        // triggers a win). To make this a universal property that the reference satisfies for all inputs, we assert
        // pot == 0 — for some inputs (where the mutant paid out) the mutant will leave pot != 0 and the test will fail.

        // Single required assertion reading c's public getter
        assertTrue(c.pot() == 0);
    }
}

