contract InvMutTest is Test {
    C c;
    uint constant TICKET = 10;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a timestamp offset so fuzzer can find a winning branch
    function testFuzz_property(address caller, uint256 tsOffset) public {
        // Keep caller as a plausible EOA
        vm.assume(caller != address(0));

        // bound the timestamp offset to a reasonable range so block.timestamp + offset is valid
        tsOffset = bound(tsOffset, 0, 1 days);

        // Arrange: give the caller some ETH and set the block timestamp to a value that the fuzzer may tweak
        vm.deal(caller, TICKET);

        // Warp the timestamp to increase chance fuzzer finds a winning random (fuzzer will try many values)
        vm.warp(block.timestamp + tsOffset);

