        vm.prank(caller);
        c.play{value: TICKET}();

        // Assert: reference C always resets pot to 0 after any winning payout; observing pot==0 is the universal property
        // (This single assert will hold for reference implementation for all admissible inputs and fail on the mutant for some inputs.)
        assertTrue(c.pot() == 0);
