contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the caller address and a uint256 nonce to vary block.timestamp via vm.warp
    // so randomness outcome can differ; we keep amount fixed (play() enforces ticket amount)
    function testFuzz_property(address caller, uint256 t) public {
        // Keep caller non-zero
        vm.assume(caller != address(0));
        // Ensure caller has funds to pay the ticket
        vm.deal(caller, 1 ether);

        // Record pot before the call
        uint256 potBefore = c.pot();

