pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET_AMOUNT = 10;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a timestamp to influence the PRNG
    function testFuzz_property(address actor, uint256 ts) public {
        // admissible domain: actor must be non-zero and not the contract or bank
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // bound timestamp to reasonable block time range
        ts = bound(ts, 1, type(uint64).max);

        // ensure actor has funds to pay the ticket
        vm.deal(actor, 1 ether);

        // set block.timestamp to the fuzzed ts so the PRNG can produce different outcomes
        vm.warp(ts);

        // make the call from the fuzzed actor sending exactly TICKET_AMOUNT
        vm.prank(actor);
        // call must succeed (revert on wrong value would be inadmissible); we're sending exact ticket
        c.play{value: TICKET_AMOUNT}();

        // After any admissible single play() with exact ticket, the reference guarantees pot <= TICKET_AMOUNT.
        // The mutant that fails to reset pot after paying out can leave pot > TICKET_AMOUNT for some inputs.
        uint potAfter = c.pot();
        assertTrue(potAfter <= TICKET_AMOUNT);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive a single play and then assert the pot behavior for a loss
    function runPlayOnLoss(uint ticketAmount, uint sendAmount) public payable {
        // Preconditions: caller supplies enough ETH to send to c
        require(ticketAmount == 10, "ticket must match contract's TICKET_AMOUNT");
        require(sendAmount == ticketAmount, "must send exactly the ticket amount");
        require(address(this).balance >= sendAmount, "insufficient balance for test");

        uint beforePot = c.pot();
        uint beforeBalanceC = address(c).balance;

        // perform the play (state-changing call must be top-level)
        c.play{value: sendAmount}();

        uint afterPot = c.pot();
        uint afterBalanceC = address(c).balance;

        // If this call corresponded to a loss (i.e., pot should NOT be drained to player), then
        // on the original contract the pot is unchanged by a losing play and the contract's balance
        // only increases by the ticketAmount; the mutant drains or refunds causing different pot change.
        assert(afterPot == beforePot + ticketAmount && afterBalanceC == beforeBalanceC + ticketAmount);
    }

    // allow funding this contract for tests
    receive() external payable {}
}

